func readMarkdown(filename string, data []byte) (Document, error) {
	writer := newDeckWriter(filename, titleOf(filename))
	var table [][]string
	flush := func() {
		if len(table) > 0 {
			writer.table(table)
			table = nil
		}
	}
	// handle reads one line, and is told the line after it because a sentence
	// with a row of "=" under it is a heading rather than a sentence. It returns
	// whether it took that next line with it, so the caller does not read the
	// underline as a line of its own.
	var handle func(line, next string) bool
	handle = func(line, next string) bool {
		if heading, ok := atxHeading(line); ok {
			flush()
			writer.slide(heading)
			return false
		}
		if rest, quoted := withoutQuoteMarker(line); quoted {
			// A quote says where a sentence came from; it is not part of the
			// sentence. Left on, the marker reached the slide with a backslash in
			// front of it — escapeLine protects a line opening with ">" because that
			// is how the deck DSL writes a cover subtitle — so the author who quoted
			// a line got "- \> 인용입니다." for it. The marker comes off here, in the
			// reader, rather than out of escapeLine: a point opening with ">" that
			// the Word or PDF reader built out of a paragraph still has to be
			// protected, and only this reader knows the character was markup.
			//
			// Taking it off and reading the line again is what makes a quote the
			// outermost block it is in markdown: the heading, list item or table row
			// somebody wrote inside the quote is then read as that block, by the
			// cases below, with no rule of its own repeated here. The recursion ends
			// because it happens only on a line that gave up at least one ">".
			//
			// Two things it deliberately does not do. It does not join the lines of
			// one quote into a single point: the only block this reader carries
			// across lines is a table, and a second one would have to answer to
			// maximumPoints, which may have moved the earlier lines onto a "(계속)"
			// by the time the quote ends. And it does not unquote next — a "> 제목"
			// over a "> ===" is a heading this reader does not claim to read, and
			// handing the stripped line ahead to the lookahead would make next mean
			// something other than the line the caller is about to skip.
			if rest == "" {
				// A marker with nothing after it is how a quote writes a blank line,
				// and a blank line is what it is read as.
				flush()
				return false
			}
			return handle(rest, next)
		}
		switch {
		case line == "":
			flush()
		case strings.HasPrefix(line, "|"):
			cells := strings.Split(strings.Trim(line, "|"), "|")
			for index := range cells {
				cells[index] = strings.TrimSpace(cells[index])
			}
			// The |---|---| rule under a header row is punctuation, not a row.
			if isRule(cells) {
				return false
			}
			table = append(table, cells)
		case isThematicBreak(line):
			// A rule separates; it has nothing to put on a slide. flush() is here
			// because a rule ends a block at least as firmly as a blank line does,
			// and the one block this reader carries across lines is a table: two
			// tables drawn with a rule between them must not run into one grid
			// whose fourth row is another table's header.
			//
			// This case comes before the list one because "- - -" is a rule drawn
			// with the character a list is drawn with, and withoutListMarker would
			// take the leading "- " off it and leave "- -" as a point.
			flush()
		case isListLine(line):
			flush()
			point, _ := withoutListMarker(line)
			writer.point(point)
		default:
			flush()
			if underlinesHeading(next) {
				writer.slide(line)
				return true
			}
			writer.point(line)
		}
		return false
	}
	// Inside a fenced code block, a line is not markdown.
	//
	// Reading every line the same way turned a runbook's one page into several
	// slides nobody wrote: the "# 1단계" of a shell comment started a slide, the
	// ``` lines stayed as bullets, and the sentence after the block landed on the
	// slide the last line of code had made. So the block is read as the one thing
	// it is, and counted, because a deck has nothing that draws code.
	var fence string
	var held []string
	blocks, skipped := 0, 0
	lines := strings.Split(strings.ReplaceAll(string(data), "\r\n", "\n"), "\n")
	// A header the document wrote about itself is not a line of the document. It
	// is cut from the slice rather than counted past, so that the lookahead and
	// the skip flag below go on meaning what they say.
	lines = lines[frontMatterLines(lines):]
	// skip says the line coming up is the underline of the heading just written,
	// which the heading has already accounted for.
	skip := false
	for index, raw := range lines {
		line := strings.TrimSpace(raw)
		if fence == "" {
			if skip {
				skip = false
				continue
			}
			if opened := fenceOf(line); opened != "" {
				flush()
				fence = opened
				// The opening line is held with the block: if the fence turns out
				// never to close, it is a line of the document again.
				held = []string{line}
				continue
			}
			skip = handle(line, lineAfter(lines, index))
			continue
		}
		held = append(held, line)
		if closesFence(line, fence) {
			blocks++
			// The two fence lines are punctuation; what did not arrive is the
			// lines between them.
			skipped += len(held) - 2
			fence, held = "", nil
		}
	}
