// is not one.
func TestARuleAroundTheBodyIsNotFrontMatter(t *testing.T) {
	document, err := Read("월간 보고서.md", []byte(
		"---\n\n# 분기 요약\n문장입니다.\n---\n"))
	if err != nil {
