	}
	expected := "# 분기 요약\n@cover\n> 월간 보고서.md\n\n" +
		"# 분기 요약\n- \\####### 일곱개\n- 매출이 늘었습니다.\n" +
		"!source 월간 보고서.md | 분기 요약\n\n"
	if document.Source != expected {
